<?php

declare(strict_types=1);

namespace Tomaj\Form\Renderer\Tests;

use Nette\Forms\Form;
use Nette\Utils\Html;

/**
 * Forms rendered by RendererTest. The expected HTML in tests/fixtures/<renderer>/<case>.html was
 * generated by rendering these forms with the renderers as they were before the TypeError fix
 * (commit 0b1b49f), so the tests show that the output did not change.
 */
final class FormCases
{
    /**
     * @return array<string, \Closure(): Form>
     */
    public static function all(): array
    {
        return [
            'text-inputs' => self::textInputs(...),
            'textarea' => self::textarea(...),
            'select' => self::select(...),
            'checkbox' => self::checkbox(...),
            'checkbox-list' => self::checkboxList(...),
            'radio-list' => self::radioList(...),
            'upload' => self::upload(...),
            'hidden' => self::hidden(...),
            'required' => self::required(...),
            'errors' => self::errors(...),
            'groups' => self::groups(...),
            'buttons' => self::buttons(...),
            'button-string-class' => self::buttonStringClass(...),
            'button-string-class-without-btn' => self::buttonStringClassWithoutBtn(...),
            'button-string-class-btn-prefix' => static fn(): Form => self::buttonsWithClass('btn-lg'),
            'button-add-class' => self::buttonAddClass(...),
            'button-add-class-with-btn' => self::buttonAddClassWithBtn(...),
            'button-array-class' => self::buttonArrayClass(...),
            'button-array-class-with-btn' => self::buttonArrayClassWithBtn(...),
            'button-disabled-class' => self::buttonDisabledClass(...),
            'button-first-has-btn-class' => self::buttonFirstHasBtnClass(...),
            'complete' => self::complete(...),
        ];
    }

    /**
     * For cases that used to crash (class stored as an array), a form with the same classes
     * set as a string, which the old code could render. The expected HTML of the crashing case
     * is the old rendering of this equivalent form.
     *
     * @return array<string, \Closure(): Form>
     */
    public static function stringClassEquivalents(): array
    {
        return [
            'button-add-class' => self::buttonStringClassWithoutBtn(...),
            'button-add-class-with-btn' => self::buttonStringClass(...),
            'button-array-class' => static fn(): Form => self::buttonsWithClass('large wide'),
            'button-array-class-with-btn' => static fn(): Form => self::buttonsWithClass('btn btn-danger'),
            'button-disabled-class' => static function (): Form {
                $form = new Form();
                $form->addText('name', 'Name');
                $form->addSubmit('send', 'Send');
                $form->addSubmit('cancel', 'Cancel')->setHtmlAttribute('class', 'cancel');
                return $form;
            },
        ];
    }

    private static function textInputs(): Form
    {
        $form = new Form();
        $form->addText('name', 'Name')
            ->setHtmlAttribute('placeholder', 'Your name')
            ->setDefaultValue('John <Doe> & "Co"');
        $form->addPassword('password', 'Password');
        // not addEmail(): newer nette/forms add maxlength="255" to it, which would make the expected HTML version-specific
        $form->addText('email', 'E-mail')->setHtmlType('email')->addRule(Form::Email);
        $form->addInteger('age', 'Age');
        $form->addText('nolabel');
        $form->addText('described', 'Described')
            ->setOption('description', 'Some help text');
        $form->addText('html_described', 'HTML described')
            ->setOption('description', Html::el()->setHtml('Help with <code>code</code>'));
        $form->addText('disabled', 'Disabled')->setDisabled();
        return $form;
    }

    private static function textarea(): Form
    {
        $form = new Form();
        $form->addTextArea('note', 'Note', 40, 5)
            ->setDefaultValue("line 1\nline 2");
        return $form;
    }

    private static function select(): Form
    {
        $form = new Form();
        $form->addSelect('country', 'Country', ['sk' => 'Slovakia', 'cz' => 'Czechia'])
            ->setPrompt('Choose')
            ->setDefaultValue('cz');
        $form->addMultiSelect('tags', 'Tags', ['a' => 'A', 'b' => 'B', 'c' => 'C'])
            ->setDefaultValue(['a', 'c']);
        return $form;
    }

    private static function checkbox(): Form
    {
        $form = new Form();
        $form->addCheckbox('agree', 'I agree');
        $form->addCheckbox('newsletter', 'Newsletter')->setDefaultValue(true);
        return $form;
    }

    private static function checkboxList(): Form
    {
        $form = new Form();
        $form->addCheckboxList('colors', 'Colors', ['r' => 'Red', 'g' => 'Green', 'b' => 'Blue'])
            ->setDefaultValue(['g']);
        return $form;
    }

    private static function radioList(): Form
    {
        $form = new Form();
        $form->addRadioList('gender', 'Gender', ['m' => 'Male', 'f' => 'Female'])
            ->setDefaultValue('f');
        return $form;
    }

    private static function upload(): Form
    {
        $form = new Form();
        // the default size and count limits come from php.ini, so replace them with fixed ones
        $file = $form->addUpload('file', 'File');
        $file->getRules()->removeRule(Form::MaxFileSize);
        $file->addRule(Form::MaxFileSize, null, 1024);
        $files = $form->addMultiUpload('files', 'Files');
        $files->getRules()->removeRule(Form::MaxFileSize)->removeRule(Form::MaxLength);
        $files->addRule(Form::MaxFileSize, null, 1024)->addRule(Form::MaxLength, null, 5);
        return $form;
    }

    private static function hidden(): Form
    {
        $form = new Form('hiddenform');
        $form->addHidden('id', '42');
        $form->addHidden('token')->setDefaultValue('abc');
        $form->addText('name', 'Name');
        $form->addSubmit('send', 'Send');
        return $form;
    }

    private static function required(): Form
    {
        $form = new Form();
        $form->addText('name', 'Name')->setRequired('Please fill in your name.');
        $form->addText('email', 'E-mail')->setRequired()->addRule(Form::Email);
        $form->addCheckbox('terms', 'Terms')->setRequired('You must agree.');
        $form->addSelect('size', 'Size', ['s' => 'S', 'm' => 'M'])->setRequired();
        $form->addText('optional', 'Optional');
        $form->addSubmit('send', 'Send');
        return $form;
    }

    private static function errors(): Form
    {
        $form = new Form();
        $form->addText('name', 'Name')->addError('Name is wrong.');
        $form->addCheckbox('terms', 'Terms')->addError('Terms are wrong.');
        $form->addText('ok', 'OK');
        // HTML error first: nette/forms 3.2.0 leaks the previous text error into an HTML error item
        $form->addError(Html::el('strong')->setText('HTML error'));
        $form->addError('Form error <b>escaped</b>.');
        $form->addSubmit('send', 'Send');
        return $form;
    }

    private static function groups(): Form
    {
        $form = new Form();
        $form->addGroup('Personal');
        $form->addText('name', 'Name');
        $form->addGroup('Address')->setOption('description', 'Where you live');
        $form->addText('street', 'Street');
        $form->addCheckbox('primary', 'Primary address');
        $form->setCurrentGroup();
        $form->addSubmit('send', 'Send');
        return $form;
    }

    private static function buttons(): Form
    {
        $form = new Form();
        $form->addText('name', 'Name');
        $form->addSubmit('save', 'Save');
        $form->addSubmit('save_next', 'Save and next');
        $form->addButton('reset', 'Reset');
        $form->addImageButton('image', '/img/send.png', 'Send');
        return $form;
    }

    private static function buttonStringClass(): Form
    {
        return self::buttonsWithClass('btn btn-warning');
    }

    private static function buttonStringClassWithoutBtn(): Form
    {
        return self::buttonsWithClass('my-button');
    }

    private static function buttonAddClass(): Form
    {
        $form = self::buttonsWithClass(null);
        $form['custom']->getControlPrototype()->addClass('my-button');
        return $form;
    }

    private static function buttonAddClassWithBtn(): Form
    {
        $form = self::buttonsWithClass(null);
        $form['custom']->getControlPrototype()->addClass('btn btn-warning');
        return $form;
    }

    private static function buttonArrayClass(): Form
    {
        $form = self::buttonsWithClass(null);
        $form['custom']->setHtmlAttribute('class', ['large', 'wide' => true, 'off' => false, 'empty' => null]);
        return $form;
    }

    private static function buttonArrayClassWithBtn(): Form
    {
        $form = self::buttonsWithClass(null);
        $form['custom']->setHtmlAttribute('class', ['btn', 'btn-danger']);
        return $form;
    }

    /**
     * A class switched off with addClass(..., false) is not rendered and does not count as a btn class.
     */
    private static function buttonDisabledClass(): Form
    {
        $form = new Form();
        $form->addText('name', 'Name');
        $form->addSubmit('send', 'Send');
        $form->addSubmit('cancel', 'Cancel')->getControlPrototype()
            ->addClass('cancel')
            ->addClass('btn btn-link', false);
        return $form;
    }

    /**
     * A button that already has a btn class does not use up the primary style.
     */
    private static function buttonFirstHasBtnClass(): Form
    {
        $form = new Form();
        $form->addSubmit('back', 'Back')->setHtmlAttribute('class', 'btn btn-link');
        $form->addSubmit('send', 'Send');
        $form->addSubmit('draft', 'Save draft');
        return $form;
    }

    /**
     * Three submit buttons, the middle one ("custom") has the given class set as a string.
     */
    private static function buttonsWithClass(?string $class): Form
    {
        $form = new Form();
        $form->addText('name', 'Name');
        $form->addSubmit('first', 'First');
        $custom = $form->addSubmit('custom', 'Custom');
        if ($class !== null) {
            $custom->setHtmlAttribute('class', $class);
        }
        $form->addSubmit('last', 'Last');
        return $form;
    }

    private static function complete(): Form
    {
        $form = new Form('complete');
        $form->setAction('/submit');
        $form->addGroup('Account');
        $form->addText('login', 'Login')->setRequired('Login is required.')->addError('Login is taken.');
        $form->addPassword('password', 'Password')->setRequired()->addRule(Form::MinLength, 'Too short', 8);
        $form->addGroup('Profile');
        $form->addTextArea('bio', 'Bio');
        $form->addSelect('lang', 'Language', ['en' => 'English', 'sk' => 'Slovak']);
        $form->addCheckbox('public', 'Public profile');
        $form->addCheckboxList('roles', 'Roles', ['admin' => 'Admin', 'user' => 'User']);
        $form->addRadioList('theme', 'Theme', ['light' => 'Light', 'dark' => 'Dark']);
        $form->addHidden('ref', 'home');
        $form->setCurrentGroup();
        $form->addSubmit('save', 'Save');
        $form->addSubmit('cancel', 'Cancel')->setValidationScope([]);
        $form->addError('Please correct the errors.');
        return $form;
    }
}
